.darma-loader-darma-b16-submarine-dive { --accent: var(--loader-color, #0e7490); --accent-2: var(--loader-secondary-color, #67e8f9); width: var(--loader-size, 126px); height: calc(var(--loader-size, 126px) * .64); position: relative; }
.darma-loader-darma-b16-submarine-dive .darma-loader-darma-b16-submarine-dive__sub { position: absolute; left: 18%; top: 38%; width: 62%; height: 30%; border-radius: 46% 50% 50% 46% / 50%; background: linear-gradient(var(--accent-2), var(--accent)); animation: darma-loader-darma-b16-submarine-dive-sub-bob calc(var(--loader-speed, 1s) * 2.4) ease-in-out infinite; }
.darma-loader-darma-b16-submarine-dive .darma-loader-darma-b16-submarine-dive__port { position: absolute; right: 16%; top: 28%; width: 16%; height: 42%; border-radius: 50%; background: color-mix(in srgb, #fff 55%, var(--accent-2)); box-shadow: inset 0 0 0 2px color-mix(in srgb, #000 25%, transparent); }
.darma-loader-darma-b16-submarine-dive .darma-loader-darma-b16-submarine-dive__scope { position: absolute; left: 58%; bottom: 92%; width: 6%; height: 46%; border-radius: 3px; background: var(--accent); }
.darma-loader-darma-b16-submarine-dive .darma-loader-darma-b16-submarine-dive__scope::after { content: ''; position: absolute; left: 60%; top: 0; width: 130%; height: 24%; border-radius: 2px; background: var(--accent); }
.darma-loader-darma-b16-submarine-dive .darma-loader-darma-b16-submarine-dive__prop { position: absolute; left: -8%; top: 10%; width: 9%; height: 80%; border-radius: 50%; background: linear-gradient(#e2e8f0, #94a3b8); animation: darma-loader-darma-b16-submarine-dive-sub-prop calc(var(--loader-speed, 1s) * .5) linear infinite; }
.darma-loader-darma-b16-submarine-dive i { position: absolute; width: 7%; height: 7%; border-radius: 50%; background: color-mix(in srgb, var(--accent-2) 80%, transparent); box-shadow: inset 0 0 0 1px var(--accent-2); opacity: 0; animation: darma-loader-darma-b16-submarine-dive-sub-bubble calc(var(--loader-speed, 1s) * 2) ease-in infinite; }
.darma-loader-darma-b16-submarine-dive i:nth-of-type(1) { left: 26%; top: 34%; }
.darma-loader-darma-b16-submarine-dive i:nth-of-type(2) { left: 40%; top: 36%; animation-delay: calc(var(--loader-speed, 1s) * .66); }
.darma-loader-darma-b16-submarine-dive i:nth-of-type(3) { left: 54%; top: 32%; animation-delay: calc(var(--loader-speed, 1s) * 1.32); }
@keyframes darma-loader-darma-b16-submarine-dive-sub-bob { 0%, 100% { transform: translateY(0) rotate(-2deg); } 50% { transform: translateY(-7%) rotate(2deg); } }
@keyframes darma-loader-darma-b16-submarine-dive-sub-prop { 0%, 100% { transform: scaleY(1); } 50% { transform: scaleY(.18); } }
@keyframes darma-loader-darma-b16-submarine-dive-sub-bubble { 0% { opacity: 0; transform: translateY(0) scale(.4); } 25% { opacity: .9; } 100% { opacity: 0; transform: translateY(-260%) scale(1.1); } }

